<?php
/**
 * Plugin Name: 3PM Personal Playlists
 * Description: Individual-song queues and private account playlists.
 * Version: 1.0.14
 * Requires PHP: 8.1
 */
defined('ABSPATH')||exit;
final class ThreePM_Playlists {
 static function boot(){add_action('init',[__CLASS__,'register']);add_action('wp_enqueue_scripts',[__CLASS__,'assets']);add_action('woocommerce_account_my-playlists_endpoint',[__CLASS__,'screen']);add_filter('woocommerce_get_query_vars',function($v){$v['my-playlists']='my-playlists';return $v;});add_action('wp_loaded',function(){add_filter('woocommerce_account_menu_items',function($items){$out=[];foreach($items as $k=>$v){$out[$k]=$v;if($k==='woo-wallet')$out['my-playlists']='My Playlists';}return $out;},PHP_INT_MAX);});add_action('wp_ajax_threepm_playlist_share',[__CLASS__,'share']);foreach(['wp_ajax_','wp_ajax_nopriv_']as $prefix)add_action($prefix.'threepm_playlist_shared',[__CLASS__,'shared']);add_action('template_redirect',[__CLASS__,'shared_page']);foreach(['save','load','trash']as $action)add_action('wp_ajax_threepm_playlist_'.$action,[__CLASS__,$action]);foreach(['wp_ajax_','wp_ajax_nopriv_']as $prefix)add_action($prefix.'threepm_playlist_tracks',[__CLASS__,'public_tracks']);}
 static function register(){register_post_type('threepm_playlist',['label'=>'Saved Playlists','public'=>false,'show_ui'=>true,'supports'=>['title','author'],'capabilities'=>['edit_posts'=>'manage_options','edit_others_posts'=>'manage_options','publish_posts'=>'manage_options','read_private_posts'=>'manage_options','delete_posts'=>'manage_options','create_posts'=>'manage_options'],'map_meta_cap'=>true]);add_rewrite_endpoint('my-playlists',EP_PAGES);if(get_option('threepm_playlists_version')!=='1'){flush_rewrite_rules(false);update_option('threepm_playlists_version','1',false);}}
 static function assets(){wp_enqueue_script('threepm-playlists',plugin_dir_url(__FILE__).'assets/playlists.js',[],'1.0.14',true);wp_enqueue_style('threepm-playlists',plugin_dir_url(__FILE__).'assets/playlists.css',[],'1.0.14');wp_add_inline_script('threepm-playlists','window.threepmPlaylists='.wp_json_encode(['endpoint'=>admin_url('admin-ajax.php'),'nonce'=>wp_create_nonce('threepm_playlists'),'user'=>get_current_user_id(),'account'=>wc_get_account_endpoint_url('my-playlists'),'artists'=>self::artists()]).';','before');}
 static function artists(){
  $links=[];foreach(get_posts(['post_type'=>'artist','post_status'=>'publish','numberposts'=>-1]) as $artist){$name=trim(wp_strip_all_tags($artist->post_title));if($name!=='')$links[]=['name'=>$name,'url'=>get_permalink($artist->ID)];}return $links;
 }
 static function url($url){$url=(string)$url;if(str_starts_with($url,'/')&&!str_starts_with($url,'//'))$url=home_url($url);return esc_url_raw($url,['http','https']);}
 static function tracks($id){if(get_post_type($id)!=='release'||get_post_status($id)!=='publish')throw new RuntimeException('Release unavailable.');$out=[];$rows=array_values(array_filter((array)get_post_meta($id,'track_repeatable',true),'is_array'));foreach($rows as $i=>$t){$source=self::url($t['releasetrack_mp3_demo']??'');if(!$source)continue;$key=$t['threepm_id']??substr(hash('sha256',$id.':'.$i.':'.($t['releasetrack_track_title']??'').':'.($t['releasetrack_mp3_demo']??'')),0,32);$out[]=['key'=>$id.':'.$key,'release'=>$id,'track'=>$key,'releasepage'=>get_permalink($id),'releaseTitle'=>get_the_title($id),'source'=>$source,'title'=>wp_strip_all_tags($t['releasetrack_track_title']??'Untitled track'),'author'=>wp_strip_all_tags($t['releasetrack_artist_name']??''),'cover'=>get_the_post_thumbnail_url($id,'thumbnail')?:'','buy'=>self::url($t['releasetrack_buyurl']??'')];}return $out;}
 static function public_tracks(){try{$id=url_to_postid(esc_url_raw(wp_unslash($_POST['releasepage']??'')));$tracks=self::tracks($id);$source=self::url(wp_unslash($_POST['source']??''));if($source)$tracks=array_values(array_filter($tracks,fn($t)=>$t['source']===$source));if(!$tracks)throw new RuntimeException('Track unavailable.');wp_send_json_success(['tracks'=>$tracks]);}catch(Throwable $e){wp_send_json_error(['message'=>$e->getMessage()],400);}}
 static function auth(){check_ajax_referer('threepm_playlists','nonce');$uid=get_current_user_id();if(!$uid)wp_send_json_error(['message'=>'Sign in to save playlists.'],401);return $uid;}
 static function own($id,$uid){$p=get_post($id);if(!$p||$p->post_type!=='threepm_playlist'||$p->post_status!=='private'||(int)$p->post_author!==$uid)throw new RuntimeException('Playlist unavailable.');return $p;}
 static function revision($id){return hash('sha256',get_the_title($id).wp_json_encode(get_post_meta($id,'_threepm_playlist_tracks',true)));}
 static function validate($input){if(!is_array($input)||!$input||count($input)>100)throw new RuntimeException('Use between 1 and 100 tracks.');$items=[];$releases=[];$seen=[];foreach($input as $item){if(!is_array($item))throw new RuntimeException('Invalid track.');$id=absint($item['release']??0);$key=(string)($item['track']??'');if(!isset($releases[$id]))$releases[$id]=self::tracks($id);$found=false;foreach($releases[$id]as $t)if($t['track']===$key){$found=true;break;}if(!$found||isset($seen[$id.':'.$key]))throw new RuntimeException('A track changed, is unavailable or appears twice.');$seen[$id.':'.$key]=true;$items[]=['release'=>$id,'track'=>$key];}return $items;}
 static function save(){ $uid=self::auth();global $wpdb;$lock='3pm-playlists-'.get_current_blog_id().'-'.$uid;$held=false;try{$held=(int)$wpdb->get_var($wpdb->prepare('SELECT GET_LOCK(%s,3)',$lock))===1;if(!$held)throw new RuntimeException('Another save is underway.');$id=absint($_POST['id']??0);if($id){self::own($id,$uid);if(!hash_equals(self::revision($id),(string)($_POST['revision']??'')))throw new RuntimeException('Playlist changed. Reload it before saving.');}else{if(count(get_posts(['post_type'=>'threepm_playlist','post_status'=>'private','author'=>$uid,'fields'=>'ids','numberposts'=>51]))>=50)throw new RuntimeException('You can save up to 50 playlists.');}$name=sanitize_text_field(wp_unslash($_POST['name']??''));if(!$name||strlen($name)>160)throw new RuntimeException('Enter a playlist name up to 160 characters.');$items=self::validate(json_decode(wp_unslash($_POST['tracks']??''),true));$id=wp_insert_post(wp_slash(['ID'=>$id,'post_type'=>'threepm_playlist','post_status'=>'private','post_title'=>$name,'post_author'=>$uid]),true);if(is_wp_error($id))throw new RuntimeException('Playlist could not be saved.');update_post_meta($id,'_threepm_playlist_tracks',$items);$wpdb->get_var($wpdb->prepare('SELECT RELEASE_LOCK(%s)',$lock));$held=false;wp_send_json_success(['id'=>$id,'revision'=>self::revision($id),'name'=>$name]);}catch(Throwable $e){if($held)$wpdb->get_var($wpdb->prepare('SELECT RELEASE_LOCK(%s)',$lock));wp_send_json_error(['message'=>$e->getMessage()],400);}}
 static function load(){ $uid=self::auth();try{$id=absint($_POST['id']??0);$p=self::own($id,$uid);$items=(array)get_post_meta($id,'_threepm_playlist_tracks',true);$tracks=[];$cache=[];foreach($items as $item){$r=(int)$item['release'];try{if(!isset($cache[$r]))$cache[$r]=self::tracks($r);foreach($cache[$r]as $t)if($t['track']===$item['track']){$tracks[]=$t;break;}}catch(Throwable $e){}}wp_send_json_success(['id'=>$id,'revision'=>self::revision($id),'name'=>$p->post_title,'tracks'=>$tracks,'unavailable'=>count($items)-count($tracks)]);}catch(Throwable $e){wp_send_json_error(['message'=>$e->getMessage()],404);}}
 static function trash(){ $uid=self::auth();try{$id=absint($_POST['id']??0);self::own($id,$uid);if(!wp_trash_post($id))throw new RuntimeException('Playlist could not be removed.');wp_send_json_success();}catch(Throwable $e){wp_send_json_error(['message'=>$e->getMessage()],400);}}
 static function share(){ $uid=self::auth();try{$id=absint($_POST['id']??0);self::own($id,$uid);$token=(string)get_post_meta($id,'_threepm_share_token',true);if(!$token){$token=bin2hex(random_bytes(24));update_post_meta($id,'_threepm_share_token',$token);}wp_send_json_success(['url'=>add_query_arg('threepm_playlist_share',$token,home_url('/'))]);}catch(Throwable $e){wp_send_json_error(['message'=>$e->getMessage()],400);}}
 static function shared_data($token){if(!is_string($token)||!preg_match('/^[a-f0-9]{48}$/D',$token))throw new RuntimeException('Playlist unavailable.');global $wpdb;$id=(int)$wpdb->get_var($wpdb->prepare("SELECT p.ID FROM {$wpdb->posts} p INNER JOIN {$wpdb->postmeta} m ON m.post_id=p.ID WHERE p.post_type='threepm_playlist' AND p.post_status='private' AND m.meta_key='_threepm_share_token' AND m.meta_value=%s LIMIT 1",$token));if(!$id)throw new RuntimeException('Playlist unavailable.');$tracks=[];$cache=[];foreach(array_slice((array)get_post_meta($id,'_threepm_playlist_tracks',true),0,100)as $item){$r=(int)$item['release'];try{if(!isset($cache[$r]))$cache[$r]=self::tracks($r);foreach($cache[$r]as $track)if($track['track']===$item['track']){$tracks[]=$track;break;}}catch(Throwable $e){}}return ['name'=>(string)get_post_field('post_title',$id,'raw'),'tracks'=>$tracks];}
 static function shared(){try{wp_send_json_success(self::shared_data(wp_unslash($_POST['token']??'')));}catch(Throwable $e){wp_send_json_error(['message'=>'Playlist unavailable.'],404);}}
 static function shared_page(){if(!isset($_GET['threepm_playlist_share']))return;$token=wp_unslash($_GET['threepm_playlist_share']);nocache_headers();add_filter('wp_robots',fn($robots)=>['noindex'=>true,'nofollow'=>true]);try{$data=self::shared_data($token);}catch(Throwable $e){status_header(404);$data=null;}get_header();echo '<main id="qwjquerycontent" class="threepm-shared-playlist"><section><p class="threepm-shared-kicker">3PM / SHARED PLAYLIST</p><h1>'.esc_html($data?$data['name']:'Playlist unavailable').'</h1>';if($data){echo '<p>'.count($data['tracks']).(count($data['tracks'])===1?' track':' tracks').'</p><button type="button" data-shared-playlist-load="'.esc_attr($token).'">Load into player</button><p role="status" data-playlist-status></p><ol>';foreach($data['tracks']as $t)echo '<li><strong>'.esc_html($t['title']).'</strong><span>'.esc_html($t['author']).'</span><a href="'.esc_url($t['releasepage']).'">'.esc_html($t['releaseTitle']).'</a></li>';echo '</ol>';}else echo '<p>This playlist is no longer shared or has been removed.</p>';echo '</section></main>';get_footer();exit;}
 static function screen(){echo '<section class="threepm-saved-playlists"><h2>My Playlists</h2><p>Build a queue from individual songs, then use Save playlist in the player. Your saved playlists stay private until you share their link.</p>'; $items=get_posts(['post_type'=>'threepm_playlist','post_status'=>'private','author'=>get_current_user_id(),'numberposts'=>50]);if(!$items)echo '<p>You haven’t saved any playlists yet.</p>';foreach($items as $p){$tracks=(array)get_post_meta($p->ID,'_threepm_playlist_tracks',true);echo '<article class="threepm-saved-playlist"><div><h3>'.esc_html($p->post_title).'</h3><p>'.count($tracks).' tracks</p></div><div><button type="button" data-playlist-load="'.$p->ID.'">Load playlist</button><button type="button" data-playlist-trash="'.$p->ID.'">Remove</button><button type="button" data-playlist-share="'.$p->ID.'">Share</button></div></article>';}echo '<p role="status" data-playlist-status></p></section>';}
}
ThreePM_Playlists::boot();
